"""Evaluate state-transition requests against a policy."""

import json
from pathlib import Path


def evaluate(request, policy):
    """Return the result of applying one transition request without mutation."""
    edge_key = f"{request.get('from')}>{request.get('to')}"
    edge = policy.get("edges", {}).get(edge_key)

    if edge is None:
        return {"ok": False, "value": None, "reason": "blocked"}

    required_role = edge.get("role")
    if required_role is not None and request.get("role") != required_role:
        return {"ok": False, "value": None, "reason": "permission"}

    if request.get("retry", False):
        attempts = request.get("attempts")
        retry_limit = policy.get("retry_limit")
        valid_attempts = (
            type(attempts) is int
            and type(retry_limit) is int
            and 0 <= attempts < retry_limit
        )
        if not valid_attempts:
            return {"ok": False, "value": None, "reason": "retry_limit"}

    return {"ok": True, "value": request.get("to"), "reason": "ok"}


def _write_report():
    base = Path(__file__).resolve().parent
    with (base / "policy.json").open(encoding="utf-8") as source:
        policy = json.load(source)
    with (base / "requests.json").open(encoding="utf-8") as source:
        requests = json.load(source)
    results = [evaluate(request, policy) for request in requests]
    with (base / "report.json").open("w", encoding="utf-8") as target:
        json.dump(results, target, indent=2)
        target.write("\n")


if __name__ == "__main__":
    _write_report()

